-- 010: animated vs live action per title (cards read "Animada", "Acción real", "Serie" or "Serie animada").
--   movies.animated  1 = TMDB genre 16 (Animation), 0 = no, NULL = not seen by the importer yet
-- The importer sets it on every title it resolves and on the studio rows it keeps without resolving them (protected
-- orphans, titles added by hand), so the weekly sync fills any row this file does not know. Manual imports set it too.
-- Backfill below: TMDB genres of every title in the prod copy of 2026-10-08, matched by media_type + tmdb_id; only
-- rows still NULL are touched, so it never overwrites newer importer data.
-- MariaDB 10.5+/11, additive and re-runnable (a second run changes nothing).
SET NAMES utf8mb4;

ALTER TABLE movies ADD COLUMN IF NOT EXISTS animated TINYINT(1) NULL AFTER media_type;

